# Pre-prediction second reading: restrict assertions where the full context
# does not establish an institutional parent or the employer of earlier ranks.
def revise(i,affiliations,unresolved=(),negative=(),explanation=''):
    if (workflow.dest()/'references_frozen.json').exists():return
    record=b.entry(i,affiliations,unresolved=[(q,'biography_text') for q in unresolved],negative=[(q,'biography_text') for q in negative],explanation=explanation)
    rows=workflow.refs();before=next(r for r in rows if r['sample_id']==str(i))
    if before==record:return
    workflow.old.check_review(record,b.rows[i]);workflow.previous.validate_evidence(b.rows[i],record)
    rows=[record if r['sample_id']==str(i) else r for r in rows]
    path=workflow.dest()/'manual_reviews.jsonl'
    path.write_text(''.join(workflow.json.dumps(r,ensure_ascii=False)+'\n' for r in rows),encoding='utf-8')
    with (workflow.dest()/'pre_prediction_review_revisions.jsonl').open('a',encoding='utf-8') as f:
        f.write(workflow.json.dumps(dict(sample_id=str(i),before=before,after=record,reason='Second full-context manual reading before any regex predictions.'),ensure_ascii=False)+'\n')

